grub/grub-mkconfig_libDEVICE=$&#123;GRUB_DEVICE_BOOT:-$&#123;GRUB_DEVICE&#125;&#125;GRUB2_BOOT_DEVICE_ID=&quot;$(grub_get_device_id $&#123;DEVICE&#125;)&quot;export GRUB2_BOOT_DEVICE_IDGRUB2_PREPARE_ROOT_CACHE=&quot;$(prepare_grub_to_access_device $&#123;DEVICE&#125;)&quot;export GRUB2_PREPARE_ROOT_CACHEexec ostree admin instutil grub2-generate

具体实现阅读 ostree 源码，函数调用顺序如下：ot_admin_instutil_builtin_grub2_generateostree_generate_grub2_configimpl_ostree_generate_grub2_config_ostree_bootloader_grub2_generate_config   &#x2F;&#x2F; 向target_fd(实际是向标准输出)中写入引导数据
/* This implementation is quite complex; see this issue for * a starting point: * https://github.com/ostreedev/ostree/issues/717 */gboolean_ostree_bootloader_grub2_generate_config (OstreeSysroot                 *sysroot,                                          int                            bootversion,                                          int                            target_fd,                                          GCancellable                  *cancellable,                                          GError                       **error)&#123;    /* So... yeah.  Just going to hardcode these. */    static const char hardcoded_video[] = &quot;load_video\n&quot;        &quot;set gfxpayload=keep\n&quot;;    static const char hardcoded_insmods[] = &quot;insmod gzio\n&quot;;    const char *grub2_boot_device_id =        g_getenv (&quot;GRUB2_BOOT_DEVICE_ID&quot;);    const char *grub2_prepare_root_cache =        g_getenv (&quot;GRUB2_PREPARE_ROOT_CACHE&quot;);    /* We must have been called via the wrapper script */    g_assert (grub2_boot_device_id != NULL);    g_assert (grub2_prepare_root_cache != NULL);    /* Passed from the parent */    gboolean is_efi = g_getenv (&quot;_OSTREE_GRUB2_IS_EFI&quot;) != NULL;    g_autoptr(GOutputStream) out_stream = g_unix_output_stream_new (target_fd, FALSE);    g_autoptr(GPtrArray) loader_configs = NULL;    if (!_ostree_sysroot_read_boot_loader_configs (sysroot, bootversion,                                                 &amp;loader_configs,                                                 cancellable, error))        return FALSE;    g_autoptr(GString) output = g_string_new (&quot;&quot;);    for (guint i = 0; i &lt; loader_configs-&gt;len; i++)    &#123;        OstreeBootconfigParser *config = loader_configs-&gt;pdata[i];        const char *title;        const char *options;        const char *kernel;        const char *initrd;        const char *devicetree;        char *quoted_title = NULL;        char *uuid = NULL;        char *quoted_uuid = NULL;        title = ostree_bootconfig_parser_get (config, &quot;title&quot;);        if (!title)            title = &quot;(Untitled)&quot;;        kernel = ostree_bootconfig_parser_get (config, &quot;linux&quot;);        quoted_title = g_shell_quote (title);        uuid = g_strdup_printf (&quot;ostree-%u-%s&quot;, (guint)i, grub2_boot_device_id);        quoted_uuid = g_shell_quote (uuid);        g_string_append_printf (output, &quot;menuentry %s --class gnu-linux --class gnu --class os --unrestricted %s &#123;\n&quot;, quoted_title, quoted_uuid);        g_free (uuid);        g_free (quoted_title);        g_free (quoted_uuid);        /* Hardcoded sections */        g_string_append (output, hardcoded_video);        g_string_append (output, hardcoded_insmods);        g_string_append (output, grub2_prepare_root_cache);        g_string_append_c (output, &#x27;\n&#x27;);        if (!kernel)            return glnx_throw (error, &quot;No \&quot;linux\&quot; key in bootloader config&quot;);        g_string_append (output, &quot;linux&quot;);        if (is_efi)            g_string_append (output, GRUB2_EFI_SUFFIX);        else            g_string_append (output, GRUB2_SUFFIX);        g_string_append_c (output, &#x27; &#x27;);        g_string_append (output, kernel);        options = ostree_bootconfig_parser_get (config, &quot;options&quot;);        if (options)        &#123;            g_string_append_c (output, &#x27; &#x27;);            g_string_append (output, options);        &#125;        g_string_append_c (output, &#x27;\n&#x27;);        initrd = ostree_bootconfig_parser_get (config, &quot;initrd&quot;);        if (initrd)        &#123;            g_string_append (output, &quot;initrd&quot;);            if (is_efi)                g_string_append (output, GRUB2_EFI_SUFFIX);            else                g_string_append (output, GRUB2_SUFFIX);            g_string_append_c (output, &#x27; &#x27;);            g_string_append (output, initrd);            g_string_append_c (output, &#x27;\n&#x27;);        &#125;        devicetree = ostree_bootconfig_parser_get (config, &quot;devicetree&quot;);        if (devicetree)        &#123;            g_string_append (output, &quot;devicetree&quot;);            g_string_append_c (output, &#x27; &#x27;);            g_string_append (output, devicetree);            g_string_append_c (output, &#x27;\n&#x27;);        &#125;        g_string_append (output, &quot;&#125;\n&quot;);    &#125;    gsize bytes_written;    if (!g_output_stream_write_all (out_stream, output-&gt;str, output-&gt;len,                                  &amp;bytes_written, cancellable, error))        return FALSE;    return TRUE;&#125;

