生产者-消费者模型基于 Qt 实现QT实现生产者-消费者模型的demo


使用信号量实现-QSemaphore#include &lt;QCoreApplication&gt;#include &lt;QSemaphore&gt;#include &lt;QThread&gt;#include &lt;QDebug&gt;#include &lt;QQueue&gt;#include &lt;QRandomGenerator&gt;const int bufferSize = 100;QSemaphore writeSemaphore(bufferSize);QSemaphore readSemaphore;QQueue&lt;int&gt; queue;class Producer : public QThread&#123;public:    void run() override    &#123;        while (1) &#123;            static int resources_index = 0;            // 0~100ms内随机产生一个资源            QThread::msleep(QRandomGenerator::global()-&gt;bounded(100));            writeSemaphore.acquire();            queue.append(resources_index++);            qDebug() &lt;&lt; &quot;+++&quot; &lt;&lt; resources_index &lt;&lt; &quot;produced&quot;;            readSemaphore.release();        &#125;    &#125;&#125;;class Consumer : public QThread&#123;public:    void run() override    &#123;        while (1) &#123;            readSemaphore.acquire();            int resources_index = queue.takeFirst();            writeSemaphore.release();            // 0~500ms内随机消费一个资源            QThread::msleep(QRandomGenerator::global()-&gt;bounded(500));            qDebug() &lt;&lt; &quot;---&quot; &lt;&lt; resources_index &lt;&lt; &quot;consumed&quot;;        &#125;    &#125;&#125;;int main(int argc, char *argv[])&#123;    QCoreApplication a(argc, argv);    Producer producer;    Consumer consumer;    producer.start();    consumer.start();    producer.wait();    consumer.wait();    return a.exec();&#125;



使用条件变量实现-QWaitCondition#include &lt;QtCore&gt;#include &lt;QRandomGenerator&gt;const int bufferSize = 100;class Producer : public QThread&#123;public:    Producer(QWaitCondition *wc1, QWaitCondition *wc2, QMutex *mutex, QQueue&lt;int&gt; &amp;queue, QObject *parent = nullptr)        : QThread(parent)        , m_consumeWaitCondition(wc1)        , m_produceWaitCondition(wc2)        , m_mutex(mutex)        , m_queue(queue)    &#123;    &#125;    void run() override    &#123;        while(1) &#123;            // 0~100ms内随机产生一个资源            QThread::msleep(QRandomGenerator::global()-&gt;bounded(100));            m_mutex-&gt;lock();            static int resource_index = 0;            if (m_queue.size() &lt; bufferSize) &#123;                m_queue.append(resource_index++);                qDebug() &lt;&lt; &quot;+++&quot; &lt;&lt; resource_index &lt;&lt; &quot;produced&quot;;            &#125; else &#123;                m_produceWaitCondition-&gt;wait(m_mutex);            &#125;            m_mutex-&gt;unlock();            m_mutex-&gt;lock();            m_consumeWaitCondition-&gt;wakeOne();            m_mutex-&gt;unlock();        &#125;    &#125;private:    QWaitCondition *m_consumeWaitCondition;    QWaitCondition *m_produceWaitCondition;    QMutex *m_mutex;    QQueue&lt;int&gt; &amp;m_queue;&#125;;class Consumer : public QThread&#123;public:    Consumer(QWaitCondition *wc1, QWaitCondition *wc2, QMutex *mutex, QQueue&lt;int&gt; &amp;queue, QObject *parent = nullptr)        : QThread(parent)        , m_consumeWaitCondition(wc1)        , m_produceWaitCondition(wc2)        , m_mutex(mutex)        , m_queue(queue)    &#123;    &#125;    void run() override    &#123;        while (1) &#123;            int resources_index = -1;            m_mutex-&gt;lock();            if (m_queue.size() &gt; 0) &#123;                resources_index = m_queue.takeFirst();                m_mutex-&gt;unlock();            &#125; else &#123;                m_consumeWaitCondition-&gt;wait(m_mutex);                m_mutex-&gt;unlock();            &#125;            m_mutex-&gt;lock();            m_produceWaitCondition-&gt;wakeAll();            m_mutex-&gt;unlock();            // 0~500ms内随机消费一个资源            QThread::msleep(QRandomGenerator::global()-&gt;bounded(500));            qDebug() &lt;&lt; &quot;---&quot; &lt;&lt; resources_index &lt;&lt; &quot;consumed&quot;;        &#125;    &#125;private:    QWaitCondition *m_consumeWaitCondition;    QWaitCondition *m_produceWaitCondition;    QMutex *m_mutex;    QQueue&lt;int&gt; &amp;m_queue;&#125;;int main(int argc, char *argv[])&#123;    QCoreApplication app(argc, argv);    QWaitCondition queueNotEmpty;    QWaitCondition queueNotFull;    QMutex mutex;    QQueue&lt;int&gt; taskQueue;    Producer producer(&amp;queueNotEmpty, &amp;queueNotFull, &amp;mutex, taskQueue);    Consumer consumer(&amp;queueNotEmpty, &amp;queueNotFull, &amp;mutex, taskQueue);    producer.start();    consumer.start();    producer.wait();    consumer.wait();    return 0;&#125;

相信来到桌面组的都已经培训过关于DBus服务的adapter和interface的用法，这里再补充一下不借助这种方式直接获取属性，调用其方法，关联其信号的方法：
准备工作：后面会用到自定义类型，所以我们提前定义它，并实现其&lt;&lt;，&gt;&gt;操作符函数，最后要在使用之前在Qt的元类型系统和Qt D_Bus类型系统注册．以供DBus通讯体系自动识别并使用．其实现如下：
#include &lt;QDBusMessage&gt;#include &lt;QDBusArgument&gt;struct DisplayRect&#123;qint16 x;qint16 y;quint16 width;quint16 height;operator QRect() const&#123;    return QRect(x, y, width, height);&#125;&#125;;Q_DECLARE_METATYPE(DisplayRect)QDBusArgument &amp;operator&lt;&lt;(QDBusArgument &amp;argument, const DisplayRect &amp;rect);const QDBusArgument &amp;operator&gt;&gt;(const QDBusArgument &amp;argument, DisplayRect &amp;rect);QDebug operator&lt;&lt;(QDebug deg, const DisplayRect &amp;rect);QDBusArgument &amp;operator&lt;&lt;(QDBusArgument &amp;argument, const DisplayRect &amp;rect)&#123;    argument.beginStructure();    argument &lt;&lt; rect.x &lt;&lt; rect.y &lt;&lt; rect.width &lt;&lt; rect.height;    argument.endStructure();    return argument;&#125;const QDBusArgument &amp;operator&gt;&gt;(const QDBusArgument &amp;argument, DisplayRect &amp;rect)&#123;    argument.beginStructure();    argument &gt;&gt; rect.x &gt;&gt; rect.y &gt;&gt; rect.width &gt;&gt; rect.height;    argument.endStructure();    return argument;&#125;QDebug operator&lt;&lt;(QDebug deg, const DisplayRect &amp;rect)&#123;    qDebug() &lt;&lt; &quot;x:&quot; &lt;&lt; rect.x &lt;&lt; &quot;y:&quot; &lt;&lt; rect.y &lt;&lt; &quot;width:&quot; &lt;&lt; rect.width &lt;&lt; &quot;height:&quot; &lt;&lt; rect.height;    return deg;&#125;


qDBusRegisterMetaType&lt;DisplayRect&gt;();进行注册
1 关联服务属性信号变化并解析当前值QDBusConnection::sessionBus().connect(&quot;com.deepin.dde.daemon.Dock&quot;,                                          &quot;/com/deepin/dde/daemon/Dock&quot;,                                          &quot;org.freedesktop.DBus.Properties&quot;,                                          &quot;PropertiesChanged&quot;,                                          &quot;sa&#123;sv&#125;as&quot;,                                          this, SLOT(handleDBusSignal(QDBusMessage)));void handleDBusSignal(const QDBusMessage &amp;msg)&#123;    QList&lt;QVariant&gt; arguments = msg.arguments();    // 参数固定长度    if (3 != arguments.count())        return;    // 返回的数据中,这一部分对应的是数据发送方的interfacename,可判断是否是自己需要的服务    QString interfaceName = msg.arguments().at(0).toString();    if (interfaceName != &quot;com.deepin.dde.daemon.Dock&quot;)        return;    QVariantMap changedProps = qdbus_cast&lt;QVariantMap&gt;(arguments.at(1).value&lt;QDBusArgument&gt;());    QStringList keys = changedProps.keys();    foreach (const QString &amp;prop, keys) &#123;        if (prop == &quot;FrontendWindowRect&quot;) &#123; // &#x27;FrontendWindowRect&#x27;属性发生变化－－－自定义类型            QVariant ret = changedProps[prop];            QDBusArgument argu = ret.value&lt;QDBusArgument&gt;();            DisplayRect rect;            argu &gt;&gt; rect;            qDebug() &lt;&lt; rect;        &#125; else if (prop == &quot;Position&quot;) &#123; // &#x27;Position&#x27;属性发生变化－－－原生类型            qDebug() &lt;&lt; &quot;Position&quot; &lt;&lt; changedProps[prop].toInt();            break;        &#125;    &#125;&#125;

２ 获取DBus服务的属性2.1 原生类型//2_1\ 获取DBus服务的属性之原生类型    QDBusInterface inter2_1(&quot;com.deepin.dde.daemon.Dock&quot;,                            &quot;/com/deepin/dde/daemon/Dock&quot;,                            &quot;com.deepin.dde.daemon.Dock&quot;,                            QDBusConnection::sessionBus(), this);    qDebug() &lt;&lt; inter2_1.property(&quot;Position&quot;).toInt();    QDBusInterface inter(&quot;com.deepin.dde.daemon.Dock&quot;,                         &quot;/com/deepin/dde/daemon/Dock&quot;,                         &quot;com.deepin.dde.daemon.Dock&quot;,                         QDBusConnection::sessionBus(), this);    auto entries = inter.property(&quot;Entries&quot;).value&lt;QList&lt;QDBusObjectPath&gt;&gt;();
2.2 自定义类型//2_2\ 获取DBus服务的属性之自定义类型 QDBusInterface inter2_2(&quot;com.deepin.daemon.Display&quot;, &quot;/com/deepin/daemon/Display&quot;, &quot;org.freedesktop.DBus.Properties&quot;); QString interafce = &quot;com.deepin.daemon.Display&quot;; QString arg1 = &quot;PrimaryRect&quot;; QDBusMessage msg = inter2_2.call(&quot;Get&quot;, interafce, arg1); QVariant var = msg.arguments().first(); QDBusVariant dbvFirst = var.value&lt;QDBusVariant&gt;(); QVariant vFirst = dbvFirst.variant(); QDBusArgument dbusArgs = vFirst.value&lt;QDBusArgument&gt;(); DisplayRect rect; dbusArgs &gt;&gt; rect; qDebug() &lt;&lt; rect;

3 调用DBus服务的方法3.1 无返回值//3_1\ 调用DBus服务的方法-无参调用-无返回值QDBusInterface inter3_1(&quot;com.deepin.dde.Clipboard&quot;,                        &quot;/com/deepin/dde/Clipboard&quot;,                        &quot;com.deepin.dde.Clipboard&quot;,                        QDBusConnection::sessionBus(), this);inter3_1.call(&quot;Toggle&quot;);

3.2 有返回值//3_2\ 调用DBus服务的方法-无参调用-有返回值QDBusInterface inter3_2(&quot;com.deepin.daemon.Network&quot;,                        &quot;/com/deepin/daemon/Network&quot;,                        &quot;com.deepin.daemon.Network&quot;,                        QDBusConnection::sessionBus(), this);QDBusMessage msg3_2 = inter3_2.call(&quot;GetProxyIgnoreHosts&quot;);qDebug() &lt;&lt; msg3_2.arguments().first().toString();

3.3 带参调用    //3_3\ 调用DBus服务的方法-带参调用    QDBusInterface inter3_3(&quot;com.deepin.deepinid.Client&quot;,                            &quot;/com/deepin/deepinid/Client&quot;,                            &quot;com.deepin.deepinid.Client&quot;,                            QDBusConnection::sessionBus(), this);inter3_3.call(&quot;Authorize&quot;, QString(&quot;clientID&quot;), QStringList(&quot;list&quot;), QString(&quot;callback&quot;), QString(&quot;state&quot;));

4 通过qdbus命令行查看属性值&#x2F;&#x2F; 获取Display服务的PrimartRect属性内容qdbus --literal  com.deepin.daemon.Display /com/deepin/daemon/Display com.deepin.daemon.Display.PrimaryRect
&#x2F;&#x2F; 获取dock的geometry属性内容qdbus --literal  com.deepin.dde.Dock /com/deepin/dde/Dock com.deepin.dde.Dock.geometry
