僵尸进程是指一个子进程已经终止但其父进程尚未读取其终止状态的进程，导致其进程表项仍然保留在系统中。


产生如果子进程先退出了，父进程还未结束并且没有调用 wait 或者 waitpid 函数获取子进程的状态信息，则子进程残留的状态信息（ task_struct 结构和少量资源信息）会变成僵尸进程。
// gcc -o zombie zombie.c#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt;#include &lt;unistd.h&gt;#include &lt;sys/types.h&gt;#include &lt;sys/wait.h&gt;int main() &#123;    pid_t pid;    // 创建子进程    pid = fork();    if (pid &lt; 0) &#123;        // fork失败        perror(&quot;fork&quot;);        exit(EXIT_FAILURE);    &#125; else if (pid == 0) &#123;        // 子进程        printf(&quot;Child process with PID: %d\n&quot;, getpid());        // 子进程立即退出        exit(EXIT_SUCCESS);    &#125; else &#123;        // 父进程        printf(&quot;Parent process with PID: %d, Child PID: %d\n&quot;, getpid(), pid);    &#125;    // 父进程继续执行其他任务，例如睡眠一段时间    printf(&quot;Parent process continue do something\n&quot;);    sleep(10);    return 0;&#125;

在终端中输入 gcc -o zombie zombie.c 进行编译，之后运行 ./zombie 进程。此时通过 ps -ef | grep zombie 可以看到 fork 后的子进程变为僵尸进程。

预防结合其产生的原因，在父进程中使用 wait 回收子进程残留的进程资源。
// gcc -o zombie zombie.c#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt;#include &lt;unistd.h&gt;#include &lt;sys/types.h&gt;#include &lt;sys/wait.h&gt;int main() &#123;    pid_t pid;    // 创建子进程    pid = fork();    if (pid &lt; 0) &#123;        // fork失败        perror(&quot;fork&quot;);        exit(EXIT_FAILURE);    &#125; else if (pid == 0) &#123;        // 子进程        printf(&quot;Child process with PID: %d\n&quot;, getpid());        // 子进程立即退出        exit(EXIT_SUCCESS);    &#125; else &#123;        // 父进程        printf(&quot;Parent process with PID: %d, Child PID: %d\n&quot;, getpid(), pid);        // 父进程等待子进程结束        int status;        pid_t wpid = wait(&amp;status);        if (wpid == -1) &#123;            perror(&quot;wait&quot;);            exit(EXIT_FAILURE);        &#125;        // 检查子进程的退出状态        if (WIFEXITED(status)) &#123;            printf(&quot;Child process exited with status %d\n&quot;, WEXITSTATUS(status));        &#125; else &#123;            printf(&quot;Child process terminated by signal %d\n&quot;, WTERMSIG(status));        &#125;    &#125;    // 父进程继续执行其他任务，例如睡眠一段时间    printf(&quot;Parent process continue do something\n&quot;);    sleep(10);    return 0;&#125;

当一个子进程结束时，内核会向其父进程发送SIGCHLD信号。父进程可以通过捕获这个信号并在信号处理函数中调用wait()或waitpid()来回收子进程的资源，从而避免僵尸进程的产生。这种方式也优雅一些。
// gcc -o zombie zombie.c#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt;#include &lt;unistd.h&gt;#include &lt;sys/types.h&gt;#include &lt;sys/wait.h&gt;#include &lt;signal.h&gt;// 信号处理函数void sigchld_handler(int signum) &#123;    // 这里可以添加一些日志记录或其他处理    printf(&quot;SIGCHLD signal received, cleaning up child processes.\n&quot;);    // 等待所有子进程结束    while (waitpid(-1, NULL, WNOHANG) &gt; 0); // WNOHANG选项使得waitpid不会阻塞&#125;int main() &#123;    // 设置信号处理函数    signal(SIGCHLD, sigchld_handler);    pid_t pid;    // 创建子进程    pid = fork();    if (pid &lt; 0) &#123;        perror(&quot;fork&quot;);        exit(EXIT_FAILURE);    &#125; else if (pid == 0) &#123;        // 子进程        printf(&quot;Child process with PID: %d\n&quot;, getpid());        sleep(5); // 模拟子进程执行操作        exit(EXIT_SUCCESS);    &#125; else &#123;        // 父进程        printf(&quot;Parent process with PID: %d, Child PID: %d\n&quot;, getpid(), pid);        // 父进程继续执行其他任务        sleep(10);        // 父进程结束前，子进程可能已经结束，信号处理函数会处理SIGCHLD信号    &#125;    return 0;&#125;

