QWeakPointer的带参构造函数是私有的，引用计数结构体使用getAndRef方法获取，value保存ptr。getAndRef只接受QObject*作为参数，因此就限制了QWeakPointer私有构造时，传入的指针类型必须为QObject.从下面的代码我们不难发现QObjectPrivate中保存了一个ExternalRefCountData的指针，此指针存在时，引用计数+1。不存在时，创建一个新的指针，并赋值引用计数(强引用为-1,弱引用为2,这个数字回头再说)后，返回此指针。
QtSharedPointer::ExternalRefCountData *QtSharedPointer::ExternalRefCountData::getAndRef(const QObject *obj)&#123;    Q_ASSERT(obj);    QObjectPrivate *d = QObjectPrivate::get(const_cast&lt;QObject *&gt;(obj));    Q_ASSERT_X(!d-&gt;wasDeleted, &quot;QWeakPointer&quot;, &quot;Detected QWeakPointer creation in a QObject being deleted&quot;);    ExternalRefCountData *that = d-&gt;sharedRefcount.load();    if (that) &#123;        that-&gt;weakref.ref();        return that;    &#125;    // we can create the refcount data because it doesn&#x27;t exist    ExternalRefCountData *x = new ExternalRefCountData(Qt::Uninitialized);    x-&gt;strongref.store(-1);    x-&gt;weakref.store(2);  // the QWeakPointer that called us plus the QObject itself    if (!d-&gt;sharedRefcount.testAndSetRelease(0, x)) &#123;        // ~ExternalRefCountData has a Q_ASSERT, so we use this trick to        // only execute this if Q_ASSERTs are enabled        Q_ASSERT((x-&gt;weakref.store(0), true));        delete x;        x = d-&gt;sharedRefcount.loadAcquire();        x-&gt;weakref.ref();    &#125;    return x;&#125;

这个时候我们看一下QObject析构时候的处理，强引用计数置0，弱引用计数-1，如果减为0则delete掉ExternalRefCountData
QObject::~QObject()&#123;    Q_D(QObject);    d-&gt;wasDeleted = true;    d-&gt;blockSig = 0; // unblock signals so we always emit destroyed()    QtSharedPointer::ExternalRefCountData *sharedRefcount = d-&gt;sharedRefcount.load();    if (sharedRefcount) &#123;        if (sharedRefcount-&gt;strongref.load() &gt; 0) &#123;            qWarning(&quot;QObject: shared QObject was deleted directly. The program is malformed and may crash.&quot;);            // but continue deleting, it&#x27;s too late to stop anyway        &#125;        // indicate to all QWeakPointers that this QObject has now been deleted        sharedRefcount-&gt;strongref.store(0);        if (!sharedRefcount-&gt;weakref.deref())            delete sharedRefcount;    &#125;

析构函数弱引用计数-1，如果减为0则delete掉d ，但是不会delete掉value
inline ~QWeakPointer() &#123; if (d &amp;&amp; !d-&gt;weakref.deref()) delete d; &#125;

