#include &lt;QApplication&gt;#include &lt;QScopedPointer&gt;#include &lt;QDebug&gt;class Children;class Parent &#123;public:    Parent() &#123;    &#125;    ~Parent() &#123;        qDebug() &lt;&lt; __FUNCTION__ ;    &#125;    // 这里将QSharedPointer改为QWeakPointer    QWeakPointer&lt;Children&gt; ptr;&#125;;class Children &#123;public:    Children() &#123;    &#125;    ~Children() &#123;        qDebug() &lt;&lt; __FUNCTION__ ;    &#125;    // 这里将QSharedPointer改为QWeakPointer    QWeakPointer&lt;Parent&gt; ptr;&#125;;int main(int argc, char *argv[])&#123;    QApplication a(argc, argv);    // 模拟一个作用域    &#123;        QSharedPointer&lt;Parent&gt; p(new Parent());        QSharedPointer&lt;Children&gt; c(new Children());        if(p &amp;&amp; c)&#123;            p-&gt;ptr = c;            c-&gt;ptr = p;        &#125;    &#125;    // 再猜测一下输出内容    return a.exec();&#125;
两个对象互相使用一个 QSharedPointer成员变量指向对方（你中有我，我中有你）。由于QSharedPointer是一个强引用的计数型指针，只有当引用数为0时，就会自动删除指针释放内存，但是如果循环引用，就会导致QSharedPointer指针的引用永远都不能为0，这时候就会导致内存无法释放。所以QWeakPointer诞生了，它就是为了打破这种循环的。并且，在需要的时候变成QSharedPointer，在其他时候不干扰QSharedPointer的引用计数。它没有重载 * 和 -&gt; 运算符，因此不可以直接通过 QWeakPointer 访问对象，典型的用法是通过 lock() 成员函数来获得 QSharedPointer，进而使用对象。
